// app/actions.js — chạy trên MÁY CHỦ; mô phỏng ý tưởng bằng hàm thường
// Hàm nhận (prevState, formData) và TRẢ LỖI NHƯ GIÁ TRỊ (không throw cho lỗi dự kiến)
async function createPost(prevState, formData) {
  const title = (formData.get("title") || "").trim();
  if (title.length < 3) return { ok: false, message: "Tiêu đề tối thiểu 3 ký tự" };
  return { ok: true, message: "Đã tạo: " + title };
}

const fd = (obj) => { const f = new FormData(); for (const k in obj) f.append(k, obj[k]); return f; };

(async () => {
  console.log((await createPost({}, fd({ title: "Hi" }))).message);
  console.log((await createPost({}, fd({ title: "Next.js" }))).message);
})();

