async function addTodo(prevState, formData) {
  const text = (formData.get("text") || "").trim();
  if (!text) return { ok: false, message: "Required" };
  return { ok: true, todos: [...prevState.todos, text] };
}
const fd = (t) => { const f = new FormData(); f.append("text", t); return f; };
(async () => {
  let s = { todos: [] };
  const r0 = await addTodo(s, fd("  "));
  console.log(r0.message);
  s = await addTodo(s, fd("a"));
  s = await addTodo(s, fd("b"));
  console.log(s.todos.join(","));
})();

