function deletePost(session, id) {
  if (!session) throw new Error("Unauthorized");
  if (session.role !== "admin") return { ok: false, status: 403 };
  return { ok: true, status: 200 };
}
try { deletePost(null, 1); } catch (e) { console.log(e.message); }
console.log(deletePost({ role: "user" }, 1).status);
